export interface OpEdExtensionEntry {
  /** 匹配键（主键）：与人工核验声明同口径（platform:id）。PCS 标注源为 QQ 音乐（qq:<numeric song id>）。 */
  songKey: string
  /** 跨平台歌曲 id（2026-10-22 补采）：同一首歌在网易云/酷狗的 id 与 QQ 不同——
   *  采集时以「歌名+主歌手+时长差 ≤10s」门控核实。缺省 = 该平台未采集（回退元数据索引）。 */
  platformIds?: { netease?: string; kugou?: string }
  bvid: string
  songTitle: string
  artists: readonly string[]
  album?: string
  /** 作品名（来自投稿标题「作品名」，与 MatchContext.franchise 同源可比对） */
  franchise?: string
  /** 歌曲在作品中的位置：op/ed/in/tm（主题曲） */
  kind: 'op' | 'ed' | 'in' | 'tm'
  /** B 站投稿标题（原样，供调试与回溯） */
  videoTitle: string
  /** 投稿 UP 主（当前全部为 PCS_Studio） */
  uploaderMid: number
  /** 歌曲完整版时长（平台元数据，秒）——延长版视频时长会明显大于该值 */
  duration: number
  /** 视频时长（秒）：延长版对齐基准 */
  videoDuration: number
  /** 标注备注（人工复核记录） */
  note?: string
  verifiedAt: string
  /** B 站播放数（2026-10-21 快照）：同曲多版本时按此取胜（用户口径：多个 UP 都做了就用播放数定胜负）。 */
  playCount?: number
}

/**
 * 「OP/ED 延长」人工核验库（2026-10-21，用户人工审核 PCS_Studio 的 OP/ED 延长内容）。
 *
 * 背景：看歌/背景的完整正片口径长期偏向"官方 MV / 录音室完整版"，而 B 站上大量动画 OP/ED
 * 只有 TV size（90 秒左右）——用户实际听的是 3-5 分钟完整版，但很少有人做高质量延长。
 * PCS_Studio（mid 8871554，2026-10 用户人工审核通过）以官方素材做"剧本级加长版"，
 * 时长对齐完整歌曲，画面为官方 OP/ED 分镜再编——是延长类的标杆 UP。
 *
 * 数据来源（离线批量标注，不实时拉取）：
 *   1. UP 主全部 201 份投稿（recArchivesByKeywords 分页拉取）；
 *   2. 剔除 2020-06 之前的早期无效内容（游戏攻略/宣传片/毕业回忆）与总集篇/自选曲/分P；
 *   3. 剩余 129 期官方歌曲 MAD 逐一以「作品名+歌曲名」到 QQ 音乐搜索标注
 *      （95 自动命中 + 16 二次修正 + 18 人工修正），songKey 与声明体系同口径（qq:数字 id）。
 *
 * 更新策略（静态快照）：该 UP 持续更新，但匹配列表**不做实时拉取**——
 *   匹配在搜索热路径上，逐歌拉 space 接口既慢又易触发 B 站风控；
 *   新投稿通过人工复核后增补本表（verifiedAt 标注核验日期），代价低且零运行时风险。
 *   查找函数 getOpEdExtensionDeclaration / getOpEdExtensionsByFranchise 均为纯 Map 查询。
 */
export const OP_ED_EXTENSION_UPLOADER_MIDS: readonly number[] = [
  8871554, // PCS_Studio（用户人工审核，延长/加长专项）
  15319615, // Aki惊蛰（2026-10-21 全量遍历 638 份投稿，完整版 OP/ED/主题曲入库）
  1592191, // 百億_光年（2026-10-21 全量遍历 1896 份投稿，完整版 OP/ED/主题曲入库）
  407183085, // 沙理戰（2026-10-23 搜索发现：回忆系列 908 期经典番 OP 完整还原 MAD·AMV，抽检通过）
  22644094, // 幻空绘星（2026-10-23 搜索发现：BD 特典 NCOP/NCED 蓝光搬运，抽检通过）
  240468109, // EVK塔克（2026-10-23 搜索发现：4K BD 修复 OP&ED 合集搬运，抽检通过）
]

/** 延长库版本：增补/修订条目时递增（并入 24h 匹配缓存指纹，旧结果自动失效）。 */
export const OP_ED_EXTENSION_VERSION = '2026-10-22-1'

