const OP_ED_EXTENSION_MAP: ReadonlyMap<string, OpEdExtensionEntry> = new Map(
  OP_ED_EXTENSION_ENTRIES.map((entry) => [entry.songKey, Object.freeze({ ...entry })]),
)

/** 同曲多版本索引（2026-10 v2）：多个 UP 都做了同一首歌的完整版/延长版时全部命中，
 *  由评分层按播放数取胜（applySameSongPlayCountPreference），不再固定押某个 UP。 */
const OP_ED_EXTENSION_MULTI_MAP: ReadonlyMap<string, readonly OpEdExtensionEntry[]> = (() => {
  const map = new Map<string, OpEdExtensionEntry[]>()
  // 索引键：主 songKey（qq:<id>）+ 跨平台 id 键（netease:<id> / kugou:<id>）——
  // 任一平台的精确 id 命中都指向同一条延长版（2026-10-22 补采）。
  const add = (key: string, entry: OpEdExtensionEntry) => {
    const list = map.get(key)
    if (list) {
      if (!list.includes(entry)) list.push(entry)
    } else map.set(key, [entry])
  }
  for (const entry of OP_ED_EXTENSION_ENTRIES) {
    add(entry.songKey, entry)
    if (entry.platformIds?.netease) add(`netease:${entry.platformIds.netease}`, entry)
    if (entry.platformIds?.kugou) add(`kugou:${entry.platformIds.kugou}`, entry)
  }
  return new Map(Array.from(map.entries(), ([key, list]) => [key, Object.freeze(list)]))
})()

/** 按歌曲精确查找（songKey = platform:id，与 getDeveloperBilibiliMvDeclaration 同口径）。
 *  同曲多版本时返回 B 站播放数最高者（其余版本仍在缓存链里可用）。 */
export function getOpEdExtensionDeclaration(songKey: string): OpEdExtensionEntry | null {
  const versions = OP_ED_EXTENSION_MULTI_MAP.get(songKey)
  if (!versions?.length) return OP_ED_EXTENSION_MAP.get(songKey) || null
  return versions.reduce((a, b) => ((b.playCount ?? 0) > (a.playCount ?? 0) ? b : a))
}

/** 同曲全部已知版本（跨 UP）。 */
export function getOpEdExtensionVersions(songKey: string): readonly OpEdExtensionEntry[] {
  return OP_ED_EXTENSION_MULTI_MAP.get(songKey) || []
}

/** 按作品名（franchise）查找该作品下全部延长版：作品语境命中时用于召回补充。 */
export function getOpEdExtensionsByFranchise(franchise: string): readonly OpEdExtensionEntry[] {
  const key = String(franchise || '').trim()
  if (!key) return []
  return OP_ED_EXTENSION_ENTRIES.filter((entry) => entry.franchise === key)
}

/** 该 bvid 是否为已知延长版投稿（候选评分时的 UP 主信任判断）。 */
export function isOpEdExtensionUploader(mid: number | undefined, author?: string): boolean {
  if (mid != null && OP_ED_EXTENSION_UPLOADER_MIDS.includes(mid)) return true
  return false
}

// ===== 全平台元数据回退索引（2026-10 v3）=====
// 延长库的 songKey 以 QQ 数字 id 为锚（qq:<id>），但用户在网易云/酷狗/Apple/汽水等平台
// 播放时拿不到 QQ id——声明注入会整库失效。这里建一个**平台无关**的元数据索引：
// 规范化（歌名+主歌手）→ 候选条目（含时长），匹配时按时长容差择优。纯静态构建、零网络。

/** 轻量规范化：与 services/bilibiliApi.normalizeText 同口径的子集（全角折叠/繁转简不做——
 *  库内条目来自单一数据源，写入时已对齐；这里只消歧分隔符/大小写/空白）。 */
function normalizeForExtensionIndex(value: string): string {
  return String(value || '')
    .normalize('NFC')
    .toLowerCase()
    .replace(/[（()）\[\]【】《》<>{}"''“”·…!！?？,，.。｡;；:：\-—_／/\|&*^%$#@~`+=～~]/g, '')
    .replace(/\s+/g, '')
}

/** 剥平台常见的版本后缀（完整版/加长版/TV size/伴奏等）：歌名主体跨平台写法差异的主要来源 */
function stripVersionSuffix(value: string): string {
  return String(value || '')
    .replace(/\s*[（(][^（）()]*[）)]\s*$/, '')
    .replace(/\s*[-–—]\s*(?:TV|Anime|Full|Short|Movie|剧场版|Sped|Slowed)\s*(?:Size|Ver(?:sion)?|Edit|Up)?.*$/i, '')
    .replace(/\s*(?:完整版|加长版|加長版|完整版自制|TV版|tv版|アニメサイズ|フルサイズ|电视版|纯音乐|伴奏|Live版|现场版)\s*$/i, '')
    .trim()
}

interface ExtensionIndexBucket { exact: OpEdExtensionEntry[]; fuzzy: OpEdExtensionEntry[] }

/** 元数据索引：normTitle|normArtist → { exact: 同名同歌手, fuzzy: 同名（歌手写法差异兜底） } */
const EXTENSION_META_INDEX: ReadonlyMap<string, ExtensionIndexBucket> = (() => {
  const map = new Map<string, ExtensionIndexBucket>()
  const push = (key: string, exact: boolean, entry: OpEdExtensionEntry) => {
    let bucket = map.get(key)
    if (!bucket) { bucket = { exact: [], fuzzy: [] }; map.set(key, bucket) }
    ;(exact ? bucket.exact : bucket.fuzzy).push(entry)
  }
  for (const entry of OP_ED_EXTENSION_ENTRIES) {
    const title = normalizeForExtensionIndex(stripVersionSuffix(entry.songTitle))
    if (!title) continue
    const firstArtist = entry.artists[0] ? normalizeForExtensionIndex(entry.artists[0]) : ''
    push(`${title}|${firstArtist}`, true, entry)
    push(`${title}|`, false, entry) // 歌手缺位/写法差异兜底桶
  }
  return map
})()

/** 时长接近判定：完整版歌曲跨平台元数据时长通常 ±10s 内；延长版视频时长不参与（duration 是歌曲口径）。 */
function isDurationClose(a: number, b: number): boolean {
  if (!a || !b) return true // 元数据缺失时不否决（交给评分层）
  return Math.abs(a - b) <= 10
}

/**
 * 全平台元数据回退查找：songKey（platform:id）未命中延长库时使用。
 * 匹配序：歌名+主歌手精确 → 歌名精确（任意歌手桶）→ 歌名前缀（剥后缀后仍长 ≥4）；
 * 每层内按时长接近度择优（播放数高者优先为 tie-break，与同曲竞争口径一致）。
 * 返回 null = 库内没有这首歌的任何版本（正常回退到普通搜索匹配）。
 */
export function findOpEdExtensionByMeta(
  songTitle: string,
  artists: readonly string[],
  duration?: number,
): OpEdExtensionEntry | null {
  const title = normalizeForExtensionIndex(stripVersionSuffix(songTitle))
  if (!title || title.length < 2) return null
  const firstArtist = artists?.[0] ? normalizeForExtensionIndex(artists[0]) : ''
  const pickBest = (candidates: readonly OpEdExtensionEntry[]): OpEdExtensionEntry | null => {
    if (!candidates.length) return null
    // 时长已知且候选全部远离（>10s）→ 大概率是同名不同版本（TV size/现场版/加长版本体），
    // 拒绝命中（宁缺毋滥：错配的声明注入比不注入更糟）。时长未知交给评分层裁决。
    if (duration) {
      const close = candidates.filter((e) => isDurationClose(e.duration, duration))
      if (!close.length) return null
      return close.reduce((a, b) => ((b.playCount ?? 0) > (a.playCount ?? 0) ? b : a))
    }
    return candidates.reduce((a, b) => ((b.playCount ?? 0) > (a.playCount ?? 0) ? b : a))
  }
  // 歌手一致判定（fuzzy/前缀层共用）：任一歌手规范化后互相包含
  const artistMatches = (entry: OpEdExtensionEntry): boolean => {
    if (!firstArtist) return true
    return entry.artists.some((a) => {
      const norm = normalizeForExtensionIndex(a)
      return norm && (norm.includes(firstArtist) || firstArtist.includes(norm))
    })
  }
  // 1) 歌名 + 主歌手
  const exactBucket = EXTENSION_META_INDEX.get(`${title}|${firstArtist}`)
  if (exactBucket?.exact.length) return pickBest(exactBucket.exact)
  // 2) 歌名（任意歌手桶）：要求歌手一致——防同名不同歌手错配
  const anyArtistBucket = EXTENSION_META_INDEX.get(`${title}|`)
  if (anyArtistBucket?.fuzzy.length) {
    const artistFiltered = anyArtistBucket.fuzzy.filter(artistMatches)
    const picked = pickBest(artistFiltered)
    if (picked) return picked
  }
  // 3) 前缀匹配（B 站标题常带「【AIR】」类前缀；库内歌名带全称）：同样要求歌手一致
  if (title.length >= 4) {
    const prefixHits: OpEdExtensionEntry[] = []
    for (const [key, bucket] of Array.from(EXTENSION_META_INDEX.entries())) {
      const keyTitle = key.split('|')[0]
      if (keyTitle.startsWith(title) || title.startsWith(keyTitle)) prefixHits.push(...bucket.exact)
    }
    const artistFiltered = prefixHits.filter(artistMatches)
    if (artistFiltered.length) return pickBest(artistFiltered)
  }
  return null
}
